require_once __DIR__.'/_common.php';
$stats=[
 ['Programmes',sponsor_count($conn,"SELECT COUNT(*) total FROM programmes"),'Total programme records','▦'],
 ['Active programmes',sponsor_count($conn,"SELECT COUNT(*) total FROM programmes WHERE status='active'"),'Currently marked active','↗'],
 ['Cohorts / intakes',sponsor_count($conn,"SELECT COUNT(*) total FROM cohorts"),'All recorded cohorts','◫'],
 ['Active candidate accounts',sponsor_count($conn,"SELECT COUNT(*) total FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug='candidate' AND u.status='active'"),'Not necessarily enrolled participants','♙'],
 ['Non-draft applications',sponsor_count($conn,"SELECT COUNT(*) total FROM applications WHERE status <> 'draft'"),'Excludes drafts','▤'],
 ['Current / completed placements',sponsor_count($conn,"SELECT COUNT(*) total FROM placements WHERE status IN ('placed','active','placement_in_progress','completed')"),'Includes placed and in-progress','✓'],
 ['Completed placements',sponsor_count($conn,"SELECT COUNT(*) total FROM placements WHERE status='completed'"),'Explicitly marked completed','★'],
 ['Attendance records · 30 days',sponsor_count($conn,"SELECT COUNT(*) total FROM candidate_attendance WHERE session_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)"),'Records in the last 30 days','◷'],
];
$programmes=sponsor_rows($conn,"SELECT p.id,p.name,p.type,p.status,p.start_date,p.end_date,COUNT(DISTINCT c.id) cohort_count,COALESCE(SUM(c.max_capacity),0) capacity FROM programmes p LEFT JOIN cohorts c ON c.programme_id=p.id GROUP BY p.id,p.name,p.type,p.status,p.start_date,p.end_date ORDER BY FIELD(p.status,'active','paused','draft','completed','archived'),p.start_date DESC LIMIT 7");
$placements=sponsor_rows($conn,"SELECT pl.placement_reference,pl.status,pl.start_date,pl.end_date,pr.name programme_name,co.name cohort_name FROM placements pl LEFT JOIN programmes pr ON pr.id=pl.programme_id LEFT JOIN cohorts co ON co.id=pl.cohort_id ORDER BY pl.created_at DESC LIMIT 6");
$statuses=sponsor_rows($conn,"SELECT status,COUNT(*) total FROM placements GROUP BY status ORDER BY total DESC");
$maxStatus=1;foreach($statuses as $s)$maxStatus=max($maxStatus,(int)$s['total']);
sponsor_header('Portfolio overview','dashboard','A high-level view of programme delivery, participation and placement outcomes.');
?>
